import React, { useState } from 'react';
import { ListBox } from 'primereact/listbox';

export default function VirtualScroll() {
    const [selectedItem, setSelectedItem] = useState(null);
    const items = Array.from({ length: 100000 }).map((_, i) => ({ label: `Item #${i}`, value: i }));

    return (
        <div className="fxb fvc fhc">
            <ListBox value={selectedItem} onChange={(e) => setSelectedItem(e.value)} options={items} 
                virtualScrollerOptions={{ itemSize: 38 }} className="w-full w250" listStyle={{ height: '250px' }} />
        </div>
    )

}